"use client";
// vendored from @patternmode/tags@3.0.0 — generated by scripts/build-registry.mjs; do not hand-edit.

import { Popover } from "@base-ui/react/popover";
import { joinClassNames } from "@/lib/patternmode/system";
import { useId, useLayoutEffect, useRef, useState } from "react";

import { TagCreationError } from "./tag-creation-error";
import { TagSelectorContext } from "./tag-selector-context";
import type { CommandOption, TagSelectorContextValue } from "./tag-selector-context";
import {
  DEFAULT_SEPARATORS,
  dedupeDrafts,
  defaultFilterOption,
  getNextIndex,
  getPreviousIndex,
  normalizeComparable,
  normalizeTag,
  toItemOption,
} from "./tag-selector-utils";
import type { TagItem, TagSelectorRootProps } from "./types";

const serializeTagItem = (item: TagItem): string => item.id;

const getExactMatches = (options: readonly TagItem[], query: string): TagItem[] => {
  const normalizedQuery = normalizeComparable(query);
  if (normalizedQuery === "") {
    return [];
  }

  return options.filter((item) => normalizeComparable(item.label) === normalizedQuery);
};

const getCommandOptions = ({
  canCreate,
  filteredOptions,
  listboxId,
  query,
}: {
  canCreate: boolean;
  filteredOptions: readonly TagItem[];
  listboxId: string;
  query: string;
}): CommandOption[] => {
  const itemOptions = filteredOptions.map((item) => toItemOption(item, listboxId));

  if (canCreate) {
    itemOptions.push({
      id: `${listboxId}-create`,
      label: `Create "${normalizeTag(query)}"`,
      type: "create",
      value: normalizeTag(query),
    });
  }

  return itemOptions;
};

const resolveDraftItem = async ({
  draft,
  onCreateItem,
  options,
}: {
  draft: string;
  onCreateItem: TagSelectorRootProps["onCreateItem"];
  options: readonly TagItem[];
}): Promise<TagItem | null> => {
  const normalizedDraft = normalizeTag(draft);
  if (normalizedDraft === "") {
    return null;
  }

  const matches = options.filter(
    (item) => normalizeComparable(item.label) === normalizeComparable(normalizedDraft),
  );
  if (matches.length === 1) {
    const [match] = matches;
    if (match === undefined || match.disabled === true) {
      return null;
    }
    return match;
  }
  if (matches.length === 0 && onCreateItem !== undefined) {
    return await onCreateItem(normalizedDraft);
  }
  return null;
};

/**
 * Resolves each distinct draft to an existing or created Tag Item. A draft
 * whose creation throws or rejects becomes a `TagCreationError` instead of
 * failing the others.
 */
const createDraftItems = async ({
  drafts,
  onCreateItem,
  options,
}: {
  drafts: readonly string[];
  onCreateItem: TagSelectorRootProps["onCreateItem"];
  options: readonly TagItem[];
}) => {
  const results = await Promise.all(
    dedupeDrafts(drafts).map(async (draft) => {
      try {
        return await resolveDraftItem({ draft, onCreateItem, options });
      } catch (error) {
        return new TagCreationError(normalizeTag(draft), { cause: error });
      }
    }),
  );

  return {
    failures: results.filter((result) => result instanceof TagCreationError),
    items: results.flatMap((result) =>
      result === null || result instanceof TagCreationError ? [] : [result],
    ),
  };
};

/**
 * Hands each failed creation to the consumer. Without a handler the failure is
 * rethrown, so a rejecting `onCreateItem` is never silently dropped.
 */
const reportCreateFailures = (
  failures: readonly TagCreationError[],
  onCreateItemError: TagSelectorRootProps["onCreateItemError"],
) => {
  if (onCreateItemError !== undefined) {
    for (const failure of failures) {
      onCreateItemError(failure);
    }
    return;
  }

  const [failure] = failures;
  if (failures.length === 1 && failure !== undefined) {
    throw failure;
  }
  if (failures.length > 1) {
    throw new AggregateError(failures, "TagSelector could not create some tags.");
  }
};

/** A ref that follows the committed value, current before any awaited continuation reads it. */
const useLatestRef = <TValue,>(value: TValue) => {
  const ref = useRef(value);
  useLayoutEffect(() => {
    ref.current = value;
  }, [value]);
  return ref;
};

const useTagSelectorRootState = (props: TagSelectorRootProps) => {
  const {
    "aria-label": ariaLabel,
    disabled = false,
    emptyMessage = "No tags found.",
    filterOption = defaultFilterOption,
    id,
    name,
    onChange,
    onCreateItem,
    onCreateItemError,
    onSearchChange,
    options,
    placeholder = "Select tags",
    renderOption,
    renderTag,
    searchValue,
    separators = DEFAULT_SEPARATORS,
    serializeItem = serializeTagItem,
    value,
  } = props;
  const generatedId = useId();
  const rootId = id ?? generatedId;
  const inputId = `${rootId}-search`;
  const listboxId = `${rootId}-listbox`;
  const [open, setOpen] = useState(false);
  const [internalQuery, setInternalQuery] = useState("");
  const [activeOptionId, setActiveOptionId] = useState<string | null>(null);
  const query = searchValue ?? internalQuery;
  const filteredOptions = options.filter((item) => filterOption(item, query));
  const exactMatches = getExactMatches(options, query);
  const canCreate =
    onCreateItem !== undefined && normalizeTag(query) !== "" && exactMatches.length === 0;
  const commandOptions = getCommandOptions({ canCreate, filteredOptions, listboxId, query });
  const latestValueRef = useLatestRef(value);

  /** The options the list actually rendered, so custom `TagSelector.List` children navigate correctly. */
  const getRenderedOptions = (): HTMLElement[] => {
    const list = document.querySelector(`#${listboxId}`);
    return list === null ? [] : [...list.querySelectorAll<HTMLElement>('[role="option"]')];
  };

  const commitValue = (nextValue: TagItem[]) => {
    latestValueRef.current = nextValue;
    onChange(nextValue);
  };

  const updateQuery = (nextQuery: string) => {
    if (searchValue === undefined) {
      setInternalQuery(nextQuery);
    }
    onSearchChange?.(nextQuery);
    setActiveOptionId(null);
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (disabled && nextOpen) {
      return;
    }
    setOpen(nextOpen);
    if (!nextOpen) {
      setActiveOptionId(null);
    }
  };

  const moveActiveOption = (direction: "next" | "previous") => {
    const renderedIds = getRenderedOptions().map((element) => element.id);
    const currentIndex = activeOptionId === null ? -1 : renderedIds.indexOf(activeOptionId);
    const nextIndex =
      direction === "next"
        ? getNextIndex(currentIndex, renderedIds.length)
        : getPreviousIndex(currentIndex, renderedIds.length);
    setActiveOptionId(renderedIds[nextIndex] ?? null);
  };

  /** Activates the highlighted option through its own click handler; false when none is rendered. */
  const selectActiveOption = (): boolean => {
    const active = getRenderedOptions().find((element) => element.id === activeOptionId);
    if (active === undefined) {
      return false;
    }
    active.click();
    return true;
  };

  const removeItem = (item: TagItem) => {
    commitValue(latestValueRef.current.filter((selectedItem) => selectedItem.id !== item.id));
  };

  const resolveDrafts = async (drafts: readonly string[]): Promise<void> => {
    if (disabled) {
      return;
    }

    const { failures, items } = await createDraftItems({ drafts, onCreateItem, options });
    const nextValue = [...latestValueRef.current];
    const nextIds = new Set(nextValue.map((item) => item.id));
    let changed = false;

    for (const item of items) {
      if (nextIds.has(item.id)) {
        continue;
      }
      nextValue.push(item);
      nextIds.add(item.id);
      changed = true;
    }

    if (changed) {
      commitValue(nextValue);
    }
    if (failures.length === 0 && (changed || items.length > 0)) {
      updateQuery("");
    }

    reportCreateFailures(failures, onCreateItemError);
  };

  const resolveDraft = async (draft: string): Promise<void> => {
    await resolveDrafts([draft]);
  };

  const selectCommandOption = async (option: CommandOption): Promise<void> => {
    if (disabled) {
      return;
    }
    if (option.type === "create") {
      await resolveDraft(option.value);
      return;
    }

    const { current } = latestValueRef;
    const isSelected = current.some((item) => item.id === option.item.id);
    if (option.item.disabled === true && !isSelected) {
      return;
    }
    commitValue(
      isSelected ? current.filter((item) => item.id !== option.item.id) : [...current, option.item],
    );
  };

  const contextValue: TagSelectorContextValue = {
    activeOptionId,
    ariaLabel,
    commandOptions,
    disabled,
    emptyMessage,
    inputId,
    listboxId,
    moveActiveOption,
    name,
    onSearchInput: updateQuery,
    open,
    placeholder,
    query,
    removeItem,
    renderOption,
    renderTag,
    resolveDraft,
    resolveDrafts,
    selectActiveOption,
    selectCommandOption,
    separators,
    serializeItem,
    setActiveOptionId,
    setOpen: handleOpenChange,
    value,
  };

  return { contextValue, handleOpenChange, rootId };
};

const TagSelectorHiddenInputs = ({ context }: { context: TagSelectorContextValue }) => {
  if (context.name === undefined || context.name === "") {
    return null;
  }

  return context.value.map((item) => (
    <input key={item.id} name={context.name} type="hidden" value={context.serializeItem(item)} />
  ));
};

export const TagSelectorRoot = (props: TagSelectorRootProps) => {
  const {
    "aria-label": _ariaLabel,
    children,
    className,
    disabled: _disabled,
    emptyMessage: _emptyMessage,
    filterOption: _filterOption,
    id: _id,
    name: _name,
    onChange: _onChange,
    onCreateItem: _onCreateItem,
    onCreateItemError: _onCreateItemError,
    onSearchChange: _onSearchChange,
    options: _options,
    placeholder: _placeholder,
    ref,
    renderOption: _renderOption,
    renderTag: _renderTag,
    searchValue: _searchValue,
    separators: _separators,
    serializeItem: _serializeItem,
    value: _value,
    ...rootProps
  } = props;
  const { contextValue, handleOpenChange, rootId } = useTagSelectorRootState(props);

  return (
    <TagSelectorContext.Provider value={contextValue}>
      <Popover.Root onOpenChange={handleOpenChange} open={contextValue.open}>
        <div
          {...rootProps}
          className={joinClassNames("patternmode-tag-selector", className)}
          data-disabled={contextValue.disabled ? "true" : undefined}
          data-slot="tag-selector"
          id={rootId}
          ref={ref}
        >
          <TagSelectorHiddenInputs context={contextValue} />
          {children}
        </div>
      </Popover.Root>
    </TagSelectorContext.Provider>
  );
};
